import type { PaymentEventType } from '../domain/payment-ledger';
import type { Payment, PaymentEventRecord, PaymentProvider } from '../domain/payment.types';

/** DI token for the persistence adapter. */
export const PAYMENT_REPOSITORY = Symbol('PAYMENT_REPOSITORY');

export interface CreatePaymentIntentInput {
  /** Generated by the service so the gateway reference can name the payment. */
  readonly id: string;
  readonly tenantId: string;
  readonly organisationId: string;
  readonly orderId: string;
  /** Paisa-formatted string, taken from the order — never from the request. */
  readonly amount: string;
  readonly currency: string;
  readonly provider: PaymentProvider;
  readonly gatewayReference: string;
  readonly idempotencyKey: string;
}

export interface AppendEventInput {
  readonly tenantId: string;
  readonly paymentId: string;
  readonly type: PaymentEventType;
  readonly amount: string;
  readonly gatewayReference?: string;
  readonly gatewayEventId?: string;
  readonly idempotencyKey?: string;
  readonly metadata?: Record<string, string>;
}

export type AppendWebhookResult =
  | { readonly kind: 'appended'; readonly event: PaymentEventRecord }
  | { readonly kind: 'duplicate'; readonly event: PaymentEventRecord | null };

export interface PaymentRepository {
  /** Business-level idempotency: the same key in the same tenant replays a payment. */
  findByIdempotencyKey(tenantId: string, idempotencyKey: string): Promise<Payment | null>;

  /** Creates the payment and its first two ledger entries atomically. */
  createWithIntent(input: CreatePaymentIntentInput): Promise<Payment>;

  findById(tenantId: string, id: string): Promise<Payment | null>;

  /**
   * Webhook lookup. There is no authenticated principal on a gateway callback,
   * so this read is explicitly unscoped inside the adapter; every scoped write
   * that follows still carries the payment's tenant.
   */
  findByIdUnscoped(id: string): Promise<Payment | null>;

  list(
    tenantId: string,
    filters: { organisationId?: string; orderId?: string; status?: string; page: number; pageSize: number },
  ): Promise<{ rows: Payment[]; total: number }>;

  /**
   * Appends one gateway event and projects its status onto the payment in the
   * same transaction. A repeated `gatewayEventId` returns `duplicate` without
   * writing anything, which is what makes duplicate-webhook delivery harmless.
   */
  appendWebhookEvent(input: AppendEventInput): Promise<AppendWebhookResult>;
}
